do $$
declare
  r record;
  v_lu_id uuid;
  v_luv_id uuid;
  v_q_id uuid;
  v_content jsonb;
begin
  for r in
    select * from (values
      ('primo_soccorso:allertamento-sicurezza-scena','Allertamento dei soccorsi e sicurezza della scena',60,'Riconoscere una situazione di emergenza, proteggere se stessi e trasmettere ai soccorsi informazioni essenziali e affidabili.','D.M. 388/2003, Allegati 3 e 4 - Modulo A: allertare il sistema di soccorso.','Qual e'' la prima priorita'' prima di avvicinarsi a una persona infortunata?','[{"id":"0","label":"Verificare che la scena sia sicura per soccorritore e infortunato"},{"id":"1","label":"Spostare subito la persona senza valutare i pericoli"},{"id":"2","label":"Cercare prima i documenti della persona"}]'::jsonb,'0',array['pericoli ancora attivi','informazioni incomplete ai soccorsi','esposizione del soccorritore'],array['valutare rapidamente la sicurezza della scena','attivare il sistema di emergenza previsto','comunicare luogo, evento, numero di persone coinvolte e pericoli presenti']),
      ('primo_soccorso:valutazione-iniziale','Valutazione iniziale dell''infortunato',60,'Osservare coscienza, respirazione e condizioni generali senza sostituirsi alla valutazione sanitaria professionale.','D.M. 388/2003, Allegati 3 e 4 - Modulo A: riconoscere un''emergenza sanitaria.','Durante la valutazione iniziale, quale elemento richiede un''attivazione immediata dei soccorsi?','[{"id":"0","label":"Una richiesta di acqua"},{"id":"1","label":"Assenza di risposta e respirazione non normale"},{"id":"2","label":"Un piccolo graffio superficiale"}]'::jsonb,'1',array['perdita di coscienza','respirazione non normale','peggioramento rapido'],array['osservare risposta e respirazione','chiedere aiuto precocemente','seguire le indicazioni della centrale di emergenza e la formazione ricevuta']),
      ('primo_soccorso:funzioni-vitali','Funzioni vitali, coscienza e respirazione',60,'Comprendere i segnali di compromissione delle funzioni vitali e il ruolo dell''addetto nell''attivazione precoce della catena dei soccorsi.','D.M. 388/2003, Allegati 3 e 4 - Modulo A; le manovre pratiche devono essere addestrate in presenza.','Se una persona non risponde e non respira normalmente, l''addetto deve principalmente:','[{"id":"0","label":"Attivare subito il sistema di emergenza e applicare le manovre per cui e'' stato addestrato"},{"id":"1","label":"Attendere alcuni minuti senza fare nulla"},{"id":"2","label":"Somministrare farmaci disponibili sul posto"}]'::jsonb,'0',array['arresto delle funzioni vitali','ritardo nell''allertamento','interventi non appropriati'],array['riconoscere rapidamente i segni critici','attivare i soccorsi','utilizzare DAE e manovre solo secondo addestramento, disponibilita'' e procedure']),
      ('primo_soccorso:traumi-emorragie','Traumi, ferite ed emorragie',60,'Riconoscere i principali traumi e le emorragie come condizioni da gestire proteggendo la persona e richiedendo assistenza sanitaria adeguata.','D.M. 388/2003, Allegati 3 e 4 - Moduli A e B: traumi in ambiente di lavoro.','In presenza di un''emorragia importante, quale comportamento e'' corretto?','[{"id":"0","label":"Proteggersi dal contatto con sangue e attivare rapidamente i soccorsi, applicando solo le tecniche apprese"},{"id":"1","label":"Ignorare la perdita di sangue se la persona parla"},{"id":"2","label":"Rimuovere sempre eventuali corpi estranei conficcati"}]'::jsonb,'0',array['emorragia significativa','contatto con fluidi biologici','peggioramento dello stato generale'],array['usare le protezioni disponibili','non improvvisare manovre invasive','monitorare la persona in attesa dei soccorsi']),
      ('primo_soccorso:traumi-scheletro-colonna','Traumi muscolo-scheletrici, cranici e della colonna',60,'Riconoscere meccanismi di trauma che possono coinvolgere arti, cranio o colonna e prevenire spostamenti non necessari.','D.M. 388/2003, Allegati 3 e 4 - Modulo A: traumi cranio-encefalici e della colonna vertebrale.','Dopo una caduta importante con possibile trauma alla colonna, in assenza di pericoli immediati e'' preferibile:','[{"id":"0","label":"Limitare gli spostamenti e attendere i soccorsi seguendo le indicazioni ricevute"},{"id":"1","label":"Far camminare subito la persona per verificare se sta bene"},{"id":"2","label":"Sollevare la persona da soli"}]'::jsonb,'0',array['trauma cranico','lesione della colonna','fratture o lussazioni'],array['considerare il meccanismo dell''incidente','evitare spostamenti non necessari','segnalare ai soccorsi dinamica e sintomi osservati']),
      ('primo_soccorso:traumi-torace-addome','Traumi del torace e dell''addome',60,'Individuare segnali di possibile trauma toracico o addominale e comprendere perche'' richiedono valutazione sanitaria tempestiva.','D.M. 388/2003, Allegati 3 e 4 - Modulo A: traumi toraco-addominali.','Dopo un forte trauma al torace o all''addome, la persona riferisce dolore crescente e difficolta'' respiratoria. Cosa fai?','[{"id":"0","label":"Attivo rapidamente i soccorsi e tengo sotto osservazione la persona senza somministrare cibi, bevande o farmaci"},{"id":"1","label":"La faccio riprendere il lavoro per distrarla"},{"id":"2","label":"Aspetto la fine del turno"}]'::jsonb,'0',array['difficolta'' respiratoria','lesioni interne non visibili','peggioramento progressivo'],array['considerare seri i traumi ad alta energia','attivare soccorso sanitario','riferire dinamica, sintomi e variazioni osservate']),
      ('primo_soccorso:emergenze-mediche','Emergenze mediche improvvise',60,'Riconoscere segnali di allarme compatibili con emergenze mediche e attivare precocemente il soccorso senza formulare diagnosi.','D.M. 388/2003, Allegati 3 e 4 - Modulo B: patologie specifiche in ambiente di lavoro.','Una persona presenta improvvisamente difficolta'' nel parlare e debolezza a un lato del corpo. L''azione corretta e'':','[{"id":"0","label":"Attivare subito il sistema di emergenza e annotare l''orario di comparsa dei sintomi se noto"},{"id":"1","label":"Aspettare che passi spontaneamente"},{"id":"2","label":"Darle un farmaco scelto da un collega"}]'::jsonb,'0',array['dolore toracico','segni neurologici improvvisi','convulsioni o alterazione dello stato di coscienza'],array['riconoscere i segnali di allarme','non somministrare farmaci di iniziativa','raccogliere informazioni utili per i soccorsi']),
      ('primo_soccorso:ustioni-intossicazioni-temperatura','Ustioni, esposizioni, intossicazioni e temperature estreme',60,'Riconoscere esposizioni a calore, freddo, sostanze o energia elettrica e dare priorita'' alla sicurezza della scena e alla decontaminazione prevista dalle procedure.','D.M. 388/2003, Allegati 3 e 4 - Moduli A e B: lesioni da freddo/calore e intossicazioni; integrare con SDS e procedure aziendali.','Davanti a una possibile esposizione chimica, prima di soccorrere e'' essenziale:','[{"id":"0","label":"Verificare il pericolo, proteggersi e seguire le procedure/SDS prima del contatto"},{"id":"1","label":"Entrare subito nell''area contaminata senza protezione"},{"id":"2","label":"Far bere qualcosa alla persona a prescindere dalla sostanza"}]'::jsonb,'0',array['contaminazione chimica','ustioni','elettrocuzione','ipotermia o ipertermia'],array['mettere in sicurezza la scena','consultare procedure e schede dati di sicurezza','attivare i soccorsi e fornire informazioni sulla sostanza o sull''evento']),
      ('primo_soccorso:gruppo-a-rischi-specifici','Gruppo A: rischi lavorativi specifici e agenti pericolosi',60,'Approfondire per le aziende di Gruppo A la relazione tra rischi dell''attivita'', possibili danni acuti e informazioni da trasmettere ai soccorsi.','D.M. 388/2003, Allegato 3 - approfondimenti per aziende di Gruppo A.','Per un''azienda di Gruppo A, la preparazione dell''addetto deve essere collegata soprattutto a:','[{"id":"0","label":"Rischi reali dell''attivita'', procedure aziendali e informazioni disponibili su agenti pericolosi"},{"id":"1","label":"Un elenco generico uguale per ogni azienda"},{"id":"2","label":"Solo al numero di dipendenti"}]'::jsonb,'0',array['agenti chimici o fisici specifici','eventi ad alta energia','scenari complessi'],array['collegare la formazione al DVR e ai rischi reali','conoscere dove reperire SDS e informazioni di emergenza','preparare comunicazioni efficaci con i soccorsi']),
      ('primo_soccorso:gruppo-a-scenari-complessi','Gruppo A: scenari complessi e coordinamento dei soccorsi',60,'Gestire dal punto di vista organizzativo scenari con piu'' persone coinvolte o rischi persistenti, senza superare il ruolo dell''addetto.','D.M. 388/2003, Allegato 3 - approfondimenti teorici; addestramento pratico separato.','In un evento con piu'' infortunati e un pericolo ancora presente, la priorita'' organizzativa e'':','[{"id":"0","label":"Evitare nuove esposizioni, attivare i soccorsi e fornire un quadro chiaro dello scenario"},{"id":"1","label":"Entrare tutti nell''area per aiutare piu'' rapidamente"},{"id":"2","label":"Spostare ogni persona senza valutare il rischio"}]'::jsonb,'0',array['piu'' persone coinvolte','pericolo persistente','comunicazioni non coordinate'],array['prevenire ulteriori vittime','coordinare allertamento e accesso dei soccorsi','mantenere informazioni aggiornate su numero di coinvolti e rischi'])
    ) as t(stable_key,title,minutes,summary,norm,quiz_q,quiz_options,correct_id,risks,prevention)
  loop
    v_content := jsonb_build_object(
      'id',split_part(r.stable_key,':',2),'title',r.title,'slide_title',r.title,'summary',r.summary,
      'detail',r.summary||' La Learning Unit supporta la parte teorica: le abilita'' manuali devono essere apprese e verificate con addestramento pratico in presenza.',
      'norm',r.norm,'minutes',r.minutes,'icon','⛑️','visual','first-aid','risks',to_jsonb(r.risks),
      'prevention',to_jsonb(r.prevention),'procedure',to_jsonb(r.prevention),'good',to_jsonb(r.prevention),
      'bad',jsonb_build_array('Improvvisare manovre non apprese','Esporsi a un pericolo non controllato','Ritardare l''attivazione dei soccorsi in presenza di segnali critici'),
      'case','Scenario guidato: applica la sequenza sicurezza della scena, riconoscimento, allertamento e assistenza entro i limiti della formazione ricevuta.',
      'question','Quali informazioni servono ai soccorsi e quale pericolo deve essere controllato prima dell''intervento?',
      'teacher','Collegare sempre i contenuti a rischi, procedure, numeri di emergenza, presidi e organizzazione reali dell''azienda.',
      'teaching_steps',jsonb_build_array('Presenta uno scenario di lavoro','Fai individuare i pericoli','Chiedi quando attivare i soccorsi','Collega la teoria all''addestramento pratico'),
      'teacher_expansion',jsonb_build_array('L''addetto di primo soccorso non sostituisce il personale sanitario: riconosce l''emergenza, protegge, allerta e applica le manovre per cui e'' stato formato.','Le decisioni devono partire dalla sicurezza della scena: creare un secondo infortunato peggiora l''evento e ostacola i soccorsi.','Il contenuto digitale non sostituisce le esercitazioni pratiche previste dal D.M. 388/2003.'),
      'quiz',jsonb_build_object('q',r.quiz_q,'answers',(select jsonb_agg(x->>'label') from jsonb_array_elements(r.quiz_options) x),'correct',r.correct_id::integer,'explanation','La risposta corretta privilegia sicurezza, attivazione precoce dei soccorsi e rispetto dei limiti della formazione.'),
      'quality',jsonb_build_object('score',100,'version','v20.025','complete',true),
      'operational',jsonb_build_object('category','first_aid','objective',r.summary,'remember','Proteggi, riconosci, allerta, assisti entro i limiti dell''addestramento ricevuto.','before',jsonb_build_array('Verifica la sicurezza della scena','Usa le protezioni previste','Attiva aiuto quando necessario'),'during',to_jsonb(r.prevention),'after',jsonb_build_array('Consegna ai soccorritori le informazioni raccolte','Segnala l''evento secondo procedura','Ripristina i presidi utilizzati secondo organizzazione aziendale'),'stop_conditions',jsonb_build_array('Pericolo non controllato','Necessita'' di manovra non appresa','Peggioramento rapido che richiede soccorso sanitario'),'adaptation','Adattare sempre a DVR, procedure aziendali, istruzioni della centrale di emergenza e formazione pratica ricevuta.'),
      'sources',jsonb_build_array(jsonb_build_object('title','D.M. 15 luglio 2003 n. 388 - Normattiva','url','https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto:2003-07-15;388!vig='),jsonb_build_object('title','D.M. 388/2003 - Ministero del Lavoro','url','https://www.lavoro.gov.it/documenti-e-norme/normative/Documents/2003/20030715_DI_388.pdf')),
      'scope',jsonb_build_object('theory_support',true,'practical_training_required',true,'internal_non_certifying',true)
    );

    insert into public.learning_units(stable_key,title,summary,default_minutes,source_group,tags,active,metadata)
    values(r.stable_key,r.title,r.summary,r.minutes,'primo_soccorso',array['primo_soccorso','emergency','dm388','theory'],true,jsonb_build_object('family','Emergenze','normative_ref','D.M. 388/2003','practical_training_required',true,'created_by_migration','v20_025'))
    on conflict (stable_key) do update set title=excluded.title,summary=excluded.summary,default_minutes=excluded.default_minutes,source_group=excluded.source_group,tags=excluded.tags,active=true,metadata=public.learning_units.metadata||excluded.metadata,updated_at=now()
    returning id into v_lu_id;

    select id into v_luv_id from public.learning_unit_versions where learning_unit_id=v_lu_id and version_number=1 limit 1;
    if v_luv_id is null then
      insert into public.learning_unit_versions(learning_unit_id,version_number,status,content,published_at) values(v_lu_id,1,'published',v_content,now()) returning id into v_luv_id;
    else
      update public.learning_unit_versions set status='published',content=v_content,published_at=coalesce(published_at,now()) where id=v_luv_id;
    end if;

    insert into public.questions(stable_key,unit_version_id,prompt,question_type,options,public_explanation,active,metadata)
    values(r.stable_key||':quiz',v_luv_id,r.quiz_q,'single_choice',r.quiz_options,null,true,jsonb_build_object('tags',array['primo_soccorso','emergency','dm388','quiz'],'difficulty','medium','assignment',jsonb_build_object('purpose','comprehension','position',0,'required',true,'unit_stable_key',r.stable_key),'created_by_migration','v20_025'))
    on conflict (stable_key) do update set unit_version_id=excluded.unit_version_id,prompt=excluded.prompt,question_type=excluded.question_type,options=excluded.options,active=true,metadata=public.questions.metadata||excluded.metadata,updated_at=now()
    returning id into v_q_id;

    insert into public.question_answer_keys(question_id,answer_key,explanation_private)
    values(v_q_id,jsonb_build_object('correct_answer',jsonb_build_object('option_id',r.correct_id)),'La risposta corretta privilegia la sicurezza del soccorritore, l''attivazione tempestiva del sistema di emergenza e l''applicazione delle sole manovre apprese.')
    on conflict (question_id) do update set answer_key=excluded.answer_key,explanation_private=excluded.explanation_private,updated_at=now();
  end loop;
end $$;

insert into public.safetymanager_course_unit_sources(external_course_code,source_group,relevance,role,metadata)
select x.code,'primo_soccorso',100,'core',jsonb_build_object('profile','first-aid-v1','created_by_migration','v20_025')
from (values ('primo_soccorso_a_16h'),('primo_soccorso_12h'),('agg_primo_soccorso_a_6h'),('agg_primo_soccorso_4h')) x(code)
on conflict (external_course_code,source_group) do update set relevance=excluded.relevance,role=excluded.role,metadata=public.safetymanager_course_unit_sources.metadata||excluded.metadata,updated_at=now();

update public.training_blueprint_sections set metadata=metadata||jsonb_build_object('source_group','primo_soccorso','digital_theory_library_ready',true),updated_at=now() where blueprint_key='first_aid_initial' and section_key='first_aid_theory';
update public.training_blueprints set status='partial',metadata=metadata||jsonb_build_object('digital_theory_library','primo_soccorso','digital_learning_units',10),updated_at=now() where stable_key in ('first_aid_initial','first_aid_update');